const body = $('Webhook Crear Corte').first().json.body;
const filas = $input.all().map(i => i.json);

const fecha_corte = String(body.fecha_corte || '').trim();
const genetica = String(body.genetica || '').trim();
const num_esquejes = parseInt(body.num_esquejes, 10);
const intervalo_dias = parseInt(body.intervalo_dias, 10) || 14;
const operario = String(body.operario || '').trim();
const observaciones = String(body.observaciones || '').trim();

if (!fecha_corte) throw new Error('falta fecha_corte');
if (!genetica) throw new Error('falta genetica');
if (!num_esquejes || num_esquejes <= 0) throw new Error('num_esquejes invalido');

const prefixMap = { 'Amnesia': 'AMN', 'Hokuzai': 'HOK' };
const prefix = prefixMap[genetica] || genetica.slice(0, 3).toUpperCase();

// Secuencial del dia para misma genetica
const mismoDia = filas.filter(f =>
  String(f.fecha_corte || '').trim() === fecha_corte &&
  String(f.genetica || '').trim() === genetica
);
const secuencial = mismoDia.length + 1;
const id_evento = prefix + '-' + fecha_corte + '-' + secuencial;

// Fecha proximo corte = fecha_corte + intervalo_dias
const d = new Date(fecha_corte + 'T00:00:00Z');
d.setUTCDate(d.getUTCDate() + intervalo_dias);
const fecha_proximo = d.getUTCFullYear() + '-' +
  String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
  String(d.getUTCDate()).padStart(2, '0');

return [{
  json: {
    id_evento,
    fecha_corte,
    genetica,
    num_esquejes,
    intervalo_dias,
    fecha_proximo_corte_estimada: fecha_proximo,
    operario,
    observaciones,
    estado: 'activo'
  }
}];

const evento = $('Preparar Evento').first().json;

// Calcular fecha = fecha_corte + N dias (UTC, mismo metodo que Preparar Evento)
function offsetDate(baseISO, days) {
  const d = new Date(baseISO + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.getUTCFullYear() + '-' +
    String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
    String(d.getUTCDate()).padStart(2, '0');
}

const trazabilidad = 'Generada por evento ' + evento.id_evento +
  ' (corte ' + evento.fecha_corte + ', ' + evento.num_esquejes + ' esquejes)';

// 4 tareas asociadas al lote — 3 mirando al esqueje + 1 a la madre
const tareas = [
  {
    offset_dias: 3,
    zona: 'esquejes',
    prioridad: 'media',
    tarea: 'Pulverizar bandejas lote ' + evento.id_evento + ' con Clonex Mist',
    observaciones: trazabilidad
  },
  {
    offset_dias: 6,
    zona: 'esquejes',
    prioridad: 'media',
    tarea: 'Pulverizar bandejas lote ' + evento.id_evento + ' con Formulez y Rhyzotonic',
    observaciones: 'Formulez 3ml/litro de agua y Rhyzo 4ml por litro de agua.'
  },
  {
    offset_dias: 9,
    zona: 'esquejes',
    prioridad: 'media',
    tarea: 'Sumergir bandejas lote ' + evento.id_evento + ' con Formulez y Rhyzotonic',
    observaciones: 'Formulez 3ml/litro de agua y Rhyzo 4ml por litro de agua. PH:5,8'
  },
  {
    offset_dias: evento.intervalo_dias,
    zona: 'madres',
    prioridad: 'alta',
    tarea: 'Evaluar vigor — proximo corte ' + evento.genetica,
    observaciones: trazabilidad
  }
];

// id unico por tarea: T + (timestamp+i) + 3 random — patron Crear_Tarea
// El +i garantiza unicidad aunque las 4 ejecuten en el mismo milisegundo
const baseTs = Date.now();
return tareas.map((t, i) => ({
  json: {
    id: 'T' + (baseTs + i) + String(Math.floor(Math.random() * 900 + 100)),
    zona: t.zona,
    tarea: t.tarea,
    prioridad: t.prioridad,
    estado: 'pendiente',
    fecha: offsetDate(evento.fecha_corte, t.offset_dias),
    recurrente: '',
    dia_recurrencia: '',
    observaciones: t.observaciones,
    id_evento_origen: evento.id_evento,
    tipo_origen: 'corte'
  }
}));

const eventos = $('Leer Eventos para Lista').all().map(i => i.json);
const reservas = $('Leer Reservas para Lista').all().map(i => i.json);

const reservasPorEvento = {};
for (const r of reservas) {
  const idEvento = String(r.id_evento || '').trim();
  if (!idEvento) continue;
  const estado = String(r.estado || '').trim().toLowerCase();
  if (estado === 'reservada' || estado === 'consumida') {
    if (!reservasPorEvento[idEvento]) reservasPorEvento[idEvento] = [];
    reservasPorEvento[idEvento].push(r);
  }
}

const items = eventos
  .map(f => {
    const id_evento = String(f.id_evento || '').trim();
    const num_esquejes = Number(f.num_esquejes) || 0;
    const n_descartados = Number(f.n_descartados) || 0;
    const total_neto = num_esquejes - n_descartados;
    const resList = reservasPorEvento[id_evento] || [];
    const reservado = resList.reduce((acc, r) => acc + (Number(r.cantidad) || 0), 0);
    const disponible = total_neto - reservado;
    return {
      id_evento,
      fecha_corte: String(f.fecha_corte || '').trim(),
      genetica: String(f.genetica || '').trim(),
      num_esquejes,
      intervalo_dias: Number(f.intervalo_dias) || 14,
      fecha_proximo_corte_estimada: String(f.fecha_proximo_corte_estimada || '').trim(),
      operario: String(f.operario || '').trim(),
      observaciones: String(f.observaciones || '').trim(),
      estado: String(f.estado || '').trim() || 'activo',
      fecha_cierre: String(f.fecha_cierre || '').trim(),
      motivo_cierre: String(f.motivo_cierre || '').trim(),
      total_neto,
      reservado,
      disponible,
      reservas_activas: resList.map(r => ({
        id_reserva: String(r.id_reserva || '').trim(),
        id_pedido: String(r.id_pedido || '').trim(),
        cantidad: Number(r.cantidad) || 0,
        estado: String(r.estado || '').trim(),
        fecha_reserva: String(r.fecha_reserva || '').trim(),
      })),
    };
  })
  .filter(f => f.id_evento)
  .sort((a, b) => {
    if (b.fecha_corte !== a.fecha_corte) return b.fecha_corte.localeCompare(a.fecha_corte);
    return b.id_evento.localeCompare(a.id_evento);
  });

return [{ json: { items } }];

const eventos = $('Leer Eventos Disponibilidad').all().map(i => i.json);
const reservas = $('Leer Reservas Disponibilidad').all().map(i => i.json);

const trigger = $('Webhook Disponibilidad').first().json;
const geneticaFilter = String((trigger.query && trigger.query.genetica) || '').trim().toLowerCase();

const reservasPorEvento = {};
for (const r of reservas) {
  const idEvento = String(r.id_evento || '').trim();
  if (!idEvento) continue;
  const estado = String(r.estado || '').trim().toLowerCase();
  if (estado === 'reservada' || estado === 'consumida') {
    reservasPorEvento[idEvento] = (reservasPorEvento[idEvento] || 0) + (Number(r.cantidad) || 0);
  }
}

const items = eventos
  .map(f => {
    const id_evento = String(f.id_evento || '').trim();
    const estado = String(f.estado || '').trim().toLowerCase() || 'activo';
    const num_esquejes = Number(f.num_esquejes) || 0;
    const n_descartados = Number(f.n_descartados) || 0;
    const total_neto = num_esquejes - n_descartados;
    const reservado = reservasPorEvento[id_evento] || 0;
    return {
      id_evento,
      genetica: String(f.genetica || '').trim(),
      fecha_corte: String(f.fecha_corte || '').trim(),
      total_neto,
      reservado,
      disponible: total_neto - reservado,
      estado,
    };
  })
  .filter(e => e.id_evento)
  .filter(e => e.estado === 'activo')
  .filter(e => !geneticaFilter || e.genetica.toLowerCase() === geneticaFilter)
  .filter(e => e.disponible > 0)
  .sort((a, b) => (a.fecha_corte || '').localeCompare(b.fecha_corte || ''));

return [{ json: { items } }];

const body = $input.first().json.body || $input.first().json;
const id_evento = String(body.id_evento || '').trim();
const motivo = String(body.motivo || 'manual').trim().toLowerCase() || 'manual';
if (!id_evento) {
  return [{ json: { ok: false, error: 'id_evento requerido', _stop: true } }];
}
return [{ json: { id_evento, motivo, ok: true } }];

const prep = $('Prepare Cerrar Lote').first().json;
if (prep._stop) return [{ json: prep }];

const eventos = $input.all().map(i => i.json);
const evento = eventos.find(e => String(e.id_evento || '').trim() === prep.id_evento);
if (!evento) {
  return [{ json: { ok: false, error: 'lote no encontrado: ' + prep.id_evento, _stop: true } }];
}
const estado = (String(evento.estado || '').trim().toLowerCase()) || 'activo';
if (estado !== 'activo') {
  return [{ json: { ok: false, error: 'lote ya cerrado: ' + prep.id_evento, _stop: true } }];
}

const hoy = new Date().toISOString().slice(0, 10);
return [{
  json: {
    id_evento: prep.id_evento,
    estado: 'cerrado',
    fecha_cierre: hoy,
    motivo_cierre: prep.motivo,
    ok: true,
  }
}];

const body = $input.first().json.body || $input.first().json;
const id_evento = String(body.id_evento || '').trim();
if (!id_evento) {
  return [{ json: { ok: false, error: 'id_evento requerido', _stop: true } }];
}
return [{ json: { id_evento, ok: true } }];

const prep = $('Prepare Reactivar Lote').first().json;
if (prep._stop) return [{ json: prep }];

const eventos = $input.all().map(i => i.json);
const evento = eventos.find(e => String(e.id_evento || '').trim() === prep.id_evento);
if (!evento) {
  return [{ json: { ok: false, error: 'lote no encontrado: ' + prep.id_evento, _stop: true } }];
}
const estado = (String(evento.estado || '').trim().toLowerCase()) || 'activo';
if (estado === 'activo') {
  return [{ json: { ok: false, error: 'lote ya activo: ' + prep.id_evento, _stop: true } }];
}

return [{
  json: {
    id_evento: prep.id_evento,
    estado: 'activo',
    fecha_cierre: '',
    motivo_cierre: '',
    ok: true,
  }
}];

const eventos = $('Read eventos_corte (cron)').all().map(i => i.json);
const reservas = $('Read reservas_pedidos (cron)').all().map(i => i.json);

const hoyStr = new Date().toISOString().slice(0, 10);
const hoyMs = new Date(hoyStr + 'T00:00:00Z').getTime();
const DIAS_LIMITE = 25;

// Mapa de reservas pendientes (estado=reservada) por evento
const reservasPorEvento = {};
for (const r of reservas) {
  const est = String(r.estado || '').trim().toLowerCase();
  if (est !== 'reservada') continue;
  const id = String(r.id_evento || '').trim();
  if (!id) continue;
  if (!reservasPorEvento[id]) reservasPorEvento[id] = { count: 0, cantidad: 0 };
  reservasPorEvento[id].count += 1;
  reservasPorEvento[id].cantidad += Number(r.cantidad) || 0;
}

const aCerrar = [];
const alertas = [];

for (const e of eventos) {
  const idEvento = String(e.id_evento || '').trim();
  if (!idEvento) continue;
  const estado = (String(e.estado || '').trim().toLowerCase()) || 'activo';
  if (estado !== 'activo') continue;

  const fecha_corte = String(e.fecha_corte || '').trim();
  if (!fecha_corte) continue;
  const corteMs = new Date(fecha_corte + 'T00:00:00Z').getTime();
  if (isNaN(corteMs)) continue;
  const dias = Math.floor((hoyMs - corteMs) / 86400000);
  if (dias < DIAS_LIMITE) continue;

  const pendientes = reservasPorEvento[idEvento];
  if (pendientes) {
    alertas.push({
      id_evento: idEvento,
      genetica: String(e.genetica || '').trim(),
      dias,
      reservas_count: pendientes.count,
      reservas_cantidad: pendientes.cantidad,
    });
  } else {
    aCerrar.push({
      id_evento: idEvento,
      estado: 'cerrado',
      fecha_cierre: hoyStr,
      motivo_cierre: 'caducado_25d',
    });
  }
}

return [{
  json: {
    has_caducados: aCerrar.length > 0,
    eventos: aCerrar,
    has_alertas: alertas.length > 0,
    alertas,
  }
}];

const data = $('Calcular Eventos Caducados 25d').first().json;
const alertas = data.alertas || [];

let texto = '⚠️ Lotes con 25d+ y reservas pendientes (' + alertas.length + ')\n\n';
for (const a of alertas) {
  texto += '• ' + a.id_evento + ' — ' + a.dias + 'd — ' + a.reservas_cantidad + ' reservados\n';
}
texto += '\nRevisar manualmente:\n' + "https://eric-crypto-ai.github.io/CuttingsClones/gestion.html?tab=cortes";

return [{
  json: {
    chat_id: 1559631681,
    text: texto,
  }
}];

const body = $('Webhook Actualizar Proximo').first().json.body || $('Webhook Actualizar Proximo').first().json;
const id_evento = String(body.id_evento || '').trim();
const nueva_fecha = String(body.nueva_fecha_proximo_corte_estimada || '').trim();

if (!id_evento) {
  return [{ json: { ok: false, error: 'falta id_evento' } }];
}
if (!nueva_fecha || !/^\d{4}-\d{2}-\d{2}$/.test(nueva_fecha)) {
  return [{ json: { ok: false, error: 'formato fecha invalido (YYYY-MM-DD)' } }];
}
const fechaTest = new Date(nueva_fecha + 'T00:00:00Z');
if (isNaN(fechaTest.getTime())) {
  return [{ json: { ok: false, error: 'fecha invalida' } }];
}

const eventos = $('Read eventos_corte (actualizar)').all().map(i => i.json);
const evento = eventos.find(e => String(e.id_evento || '').trim() === id_evento);
if (!evento) {
  return [{ json: { ok: false, error: 'lote no encontrado: ' + id_evento } }];
}
const estado = (String(evento.estado || '').trim().toLowerCase()) || 'activo';
if (estado !== 'activo') {
  return [{ json: { ok: false, error: 'lote no activo (estado=' + estado + '). No se permite editar fechas de lotes cerrados.' } }];
}

// Tarea #4 asociada (zona=madres, tipo_origen=corte, id_evento_origen=X, estado=pendiente)
const tareas = $('Read tareas (actualizar)').all().map(i => i.json);
const tarea = tareas.find(t =>
  String(t.id_evento_origen || '').trim() === id_evento &&
  String(t.tipo_origen || '').trim().toLowerCase() === 'corte' &&
  String(t.zona || '').trim().toLowerCase() === 'madres' &&
  String(t.estado || '').trim().toLowerCase() === 'pendiente'
);

return [{ json: {
  ok: true,
  id_evento: id_evento,
  fecha_proximo_corte_estimada: nueva_fecha,
  tarea_existe: !!tarea,
  id_tarea: tarea ? String(tarea.id || '').trim() : ''
} }];

const v = $('Validar Actualizar Proximo').first().json;
return [{ json: {
  ok: true,
  id_evento: v.id_evento,
  nueva_fecha: v.fecha_proximo_corte_estimada,
  tarea_actualizada: true,
  id_tarea: v.id_tarea
} }];

const v = $('Validar Actualizar Proximo').first().json;
return [{ json: {
  ok: true,
  id_evento: v.id_evento,
  nueva_fecha: v.fecha_proximo_corte_estimada,
  tarea_actualizada: false,
  motivo_sin_tarea: 'tarea #4 no existe o no esta pendiente'
} }];
